var n=`0248-loukoumades`;var t=`world-0248`;var o=`GR`;var a=`southern-europe`;var l=8;var r=65;var s={en:`Loukoumades`,ua:`Лукумадес`};var u={en:`A traditional Greece dish made with all-purpose flour, instant yeast, whole cow milk, walnut. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Греція. Основні інгредієнти: пшеничне борошно універсальне, інстантні дріжджі, цільне коров'яче молоко, волоський горіх. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var d=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:9,i:[[`all-purpose-flour`,320,`g`],[`instant-yeast`,6,`g`],[`whole-cow-milk`,260,`ml`],[`water`,100,`ml`],[`white-granulated-sugar`,25,`g`]]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 35 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 35 хвилин.`,t:[`rapid-chilling`],m:35,i:[]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 16 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 16 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:16,i:[[`sunflower-oil`,750,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:5,i:[[`honey`,155,`g`],[`ground-cinnamon`,5,`g`],[`walnut`,90,`g`]]}];var g={slug:n,id:t,country:`GR`,region:a,servings:8,minutes:65,title:s,text:u,steps:d};export{o as country,g as default,t as id,r as minutes,a as region,l as servings,n as slug,d as steps,u as text,s as title};